static struct SymbexBoolVertical B_V;
static int B_V_READY;
static inline int symbex_mlp_infer(const uint8_t* x) {
    if (!B_V_READY) {                        /* once: carve the work block, build the list table */
        if (symbex_bool_vertical_init(&symbex_net, B_VWORK, sizeof B_VWORK, &B_V)) return -1;
#if defined(SYMBEX_BOOL_VERTICAL_PREPARED_COMPACT)
        if (symbex_bool_vertical_prepare_compact(&B_V, B_VPREP, sizeof B_VPREP)) return -1;
#elif defined(SYMBEX_BOOL_VERTICAL_PREPARED)
        if (symbex_bool_vertical_prepare(&B_V, B_VPREP, sizeof B_VPREP)) return -1;
#endif
        B_V_READY = 1;
    }
    return symbex_bool_net_run_vertical(&symbex_net, &B_V, x);
}
#else
#define SYMBEX_MLP_BYTES_BUFFERS 11136u
static inline int symbex_mlp_infer(const uint8_t* x) { return symbex_bool_net_run(&symbex_net, x); }
#endif
